import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const resources = [];

  const ribbonWidth = 7.0;
  const ribbonHeight = 0.35;

  // Base ribbon plane
  const planeGeom = new THREE.PlaneGeometry(ribbonWidth, ribbonHeight);
  const planeMat = new THREE.MeshStandardNodeMaterial({
    color: 0x111117,
    roughness: 0.6,
    metalness: 0.2
  });
  const planeMesh = new THREE.Mesh(planeGeom, planeMat);
  group.add(planeMesh);
  resources.push(planeGeom, planeMat);

  // Hairlines (top and bottom)
  const hairlineGeom = new THREE.PlaneGeometry(ribbonWidth, 0.006);
  const hairlineMat = new THREE.MeshBasicNodeMaterial({ color: 0x23232b });

  const topHairline = new THREE.Mesh(hairlineGeom, hairlineMat);
  topHairline.position.y = ribbonHeight / 2 + 0.003;
  topHairline.position.z = 0.001;
  group.add(topHairline);

  const bottomHairline = new THREE.Mesh(hairlineGeom, hairlineMat);
  bottomHairline.position.y = -ribbonHeight / 2 - 0.003;
  bottomHairline.position.z = 0.001;
  group.add(bottomHairline);

  resources.push(hairlineGeom, hairlineMat);

  // Ticker items
  const tickerItems = (config.textContent && Array.isArray(config.textContent))
    ? config.textContent
    : [
        "CAL NA-01 BEAT 28800 VPH",
        "POWER RESERVE 72H",
        "CASE 40.5 MM 904L",
        "REF 5811 IN STOCK",
        "WAITLIST 1204",
        "NEXT FITTING JUL 18"
      ];

  const scrollContainer = new THREE.Group();

  // Layout calculation
  const charWidthEstimate = 0.062;
  let totalStripWidth = 0;
  const itemWidths = [];

  for (const item of tickerItems) {
    const txt = typeof item === 'string' ? item : (item.text || String(item));
    const itemWidth = txt.length * charWidthEstimate;
    itemWidths.push(itemWidth);
    totalStripWidth += itemWidth + 0.02 + 1.0;
  }

  // Render ticker strip function
  const renderTickerStrip = (xOffset) => {
    let x = xOffset;

    for (let i = 0; i < tickerItems.length; i++) {
      const item = tickerItems[i];
      const itemText = typeof item === 'string' ? item : (item.text || String(item));
      const itemW = itemWidths[i];

      // Render text via fontAtlas (MSDF)
      const textMesh = ctx.fontAtlas.createText(itemText, {
        fontSize: 13,
        fontWeight: 700,
        color: 0xe8ecf2,
        letterSpacing: 0.06
      });

      if (textMesh) {
        textMesh.position.set(x + itemW / 2, 0, 0.02);
        scrollContainer.add(textMesh);
      }

      x += itemW + 0.5;

      // Accent tick mark
      const tickGeom = new THREE.PlaneGeometry(0.02, 0.14);
      const tickMat = new THREE.MeshBasicNodeMaterial({
        color: 0xff2a38,
        emissive: 0xff2a38,
        emissiveIntensity: 1.5,
        toneMapped: false
      });
      const tickMesh = new THREE.Mesh(tickGeom, tickMat);
      tickMesh.position.set(x, 0, 0.025);
      scrollContainer.add(tickMesh);

      resources.push(tickGeom, tickMat);

      x += 0.02 + 0.5;
    }
  };

  // Render duplicated strips for seamless loop
  const startPos = -ribbonWidth / 2 + 0.25;
  renderTickerStrip(startPos);
  renderTickerStrip(startPos + totalStripWidth);

  group.add(scrollContainer);

  // Apply fly-through primitive for scrolling animation
  ctx.primitives['fly-through'](scrollContainer, {
    depthUnits: 0,
    speed: 0.4
  });

  // Edge fade texture using DataTexture
  const fadeTexWidth = 256;
  const fadeTexHeight = 1;
  const fadeData = new Uint8Array(fadeTexWidth * fadeTexHeight * 4);

  for (let i = 0; i < fadeTexWidth; i++) {
    const norm = i / fadeTexWidth;
    let alpha = 0;

    if (norm < 0.09) {
      alpha = (norm / 0.09) * 255;
    } else if (norm > 0.91) {
      alpha = ((1 - norm) / 0.09) * 255;
    } else {
      alpha = 255;
    }

    const idx = i * 4;
    fadeData[idx + 0] = 11;
    fadeData[idx + 1] = 11;
    fadeData[idx + 2] = 16;
    fadeData[idx + 3] = Math.round(alpha);
  }

  const fadeTex = new THREE.DataTexture(
    fadeData,
    fadeTexWidth,
    fadeTexHeight,
    THREE.RGBAFormat,
    THREE.UnsignedByteType
  );
  fadeTex.magFilter = THREE.LinearFilter;
  fadeTex.minFilter = THREE.LinearFilter;
  fadeTex.needsUpdate = true;

  // Fade overlay plane
  const fadeGeom = new THREE.PlaneGeometry(ribbonWidth, ribbonHeight);
  const fadeMat = new THREE.MeshBasicNodeMaterial({
    map: fadeTex,
    transparent: true,
    depthWrite: false,
    blending: THREE.MultiplyBlending
  });
  const fadePlane = new THREE.Mesh(fadeGeom, fadeMat);
  fadePlane.position.z = 0.03;
  group.add(fadePlane);

  resources.push(fadeGeom, fadeMat, fadeTex);

  // Cleanup
  group.userData.cleanup = () => {
    resources.forEach(resource => {
      if (resource && typeof resource.dispose === 'function') {
        resource.dispose();
      }
    });
  };

  group.userData.handlers = {};

  return group;
}
